import{_ as t,o as i,c as s,a2 as a}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Loi sur la Garantie Médicale","description":"","frontmatter":{},"headers":[],"relativePath":"fr/44-医疗保障法.md","filePath":"fr/44-医疗保障法.md"}'),n={name:"fr/44-医疗保障法.md"};function r(l,e,d,o,u,c){return i(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="loi-sur-la-garantie-medicale" tabindex="-1">Loi sur la Garantie Médicale <a class="header-anchor" href="#loi-sur-la-garantie-medicale" aria-label="Permalink to &quot;Loi sur la Garantie Médicale&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>44</td></tr><tr><td>Module</td><td>Système Juridique et Cadre de Gouvernance</td></tr><tr><td>Mots clés</td><td>Droit aux soins, Médecine symbiotique, Traitement des lésions de culture, Vie et santé, Système d&#39;assurance médicale</td></tr></tbody></table><h2 id="i-objectif-legislatif-et-principes-fondamentaux" tabindex="-1">I. Objectif Législatif et Principes Fondamentaux <a class="header-anchor" href="#i-objectif-legislatif-et-principes-fondamentaux" aria-label="Permalink to &quot;I. Objectif Législatif et Principes Fondamentaux&quot;">​</a></h2><p>La <em>Loi sur la Garantie Médicale</em> est l&#39;une des cinq lois d&#39;accompagnement de la Civilisation Symbiotique de l&#39;Ancre. Elle vise à garantir le droit à la santé et aux soins de toutes les vies au sein de l&#39;Univers Hengyuan, à établir un système médical symbiotique couvrant toutes les races, et à assurer que chaque vie puisse recevoir un traitement rapide et efficace en cas de blessure ou de maladie.</p><p>Cette Loi établit les principes fondamentaux suivants :</p><table tabindex="0"><thead><tr><th>Principe</th><th>Contenu</th></tr></thead><tbody><tr><td>Priorité à la santé</td><td>La vie et la santé sont le fondement de toute évolution ; l&#39;État et la civilisation placent la protection de la vie et de la santé en position prioritaire</td></tr><tr><td>Couverture universelle</td><td>La garantie médicale couvre toutes les vies, sans distinction de race, de culture, de naissance ou de situation économique</td></tr><tr><td>Diagnostic et traitement hiérarchisés</td><td>Établir un système de diagnostic et de traitement à trois niveaux — médecine de base, médecine régionale, médecine avancée — répartissant rationnellement les ressources médicales</td></tr><tr><td>Combinaison de la prévention et du traitement</td><td>Prévention d&#39;abord, combinaison de la prévention et du traitement ; accorder de l&#39;importance à la prévention et à la rééducation des lésions de culture</td></tr><tr><td>Adaptation aux autres races</td><td>Fournir des plans médicaux adaptés aux caractéristiques physiologiques des différentes races ; interdire l&#39;application uniforme des normes humaines</td></tr><tr><td>Attribut d&#39;intérêt public</td><td>Les services médicaux de base ont un attribut d&#39;intérêt public ; le droit au traitement des vies ne doit pas être privé à des fins lucratives</td></tr></tbody></table><h2 id="ii-garanties-juridiques-du-droit-a-la-vie-et-a-la-sante" tabindex="-1">II. Garanties Juridiques du Droit à la Vie et à la Santé <a class="header-anchor" href="#ii-garanties-juridiques-du-droit-a-la-vie-et-a-la-sante" aria-label="Permalink to &quot;II. Garanties Juridiques du Droit à la Vie et à la Santé&quot;">​</a></h2><p>Cette Loi stipule explicitement que le droit à la vie et à la santé est un droit fondamental conféré à chaque vie par la Constitution Symbiotique, comprenant notamment :</p><ol><li><strong>Droit aux soins médicaux de base</strong> : chaque vie a le droit de recevoir des services médicaux de base gratuits, y compris le diagnostic et le traitement des maladies courantes, les médicaments de base, les examens médicaux de routine, etc.</li><li><strong>Droit aux soins d&#39;urgence</strong> : chaque vie a le droit de recevoir des soins d&#39;urgence en cas de blessure ou de maladie soudaine ; les institutions médicales ne doivent pas refuser les soins d&#39;urgence pour quelque raison que ce soit.</li><li><strong>Droit au traitement des lésions de culture</strong> : les cultivateurs qui subissent des troubles énergétiques, des lésions des méridiens, la déviation de culture et d&#39;autres lésions pendant le processus de culture ont le droit de recevoir un traitement professionnel.</li><li><strong>Droit au consentement éclairé</strong> : les patients ont le droit de connaître leur propre état, le plan de traitement, les risques et le pronostic, et le droit de choisir ou de refuser les plans de traitement.</li><li><strong>Droit à la protection de la vie privée</strong> : les informations médicales et les données corporelles des patients sont protégées par la loi ; sans le consentement du patient, elles ne doivent pas être divulguées ou utilisées à d&#39;autres fins.</li><li><strong>Droit à la garantie de rééducation</strong> : les patients blessés et malades ont le droit de recevoir un traitement de rééducation et des appareils d&#39;assistance, les aidant à recouvrer leurs capacités de travail et de vie.</li></ol><h2 id="iii-architecture-du-systeme-medical-symbiotique" tabindex="-1">III. Architecture du Système Médical Symbiotique <a class="header-anchor" href="#iii-architecture-du-systeme-medical-symbiotique" aria-label="Permalink to &quot;III. Architecture du Système Médical Symbiotique&quot;">​</a></h2><p>Le système médical de la Civilisation Symbiotique de l&#39;Ancre est divisé en trois niveaux, avec des mécanismes de référence et de collaboration établis entre les niveaux :</p><table tabindex="0"><thead><tr><th>Niveau</th><th>Nom</th><th>Fonctions</th><th>Couverture</th></tr></thead><tbody><tr><td>Premier niveau</td><td>Poste médical de base</td><td>Diagnostic et traitement des maladies courantes, soins préventifs, examens de base, transport d&#39;urgence</td><td>Communautés/villages/petits plans</td></tr><tr><td>Deuxième niveau</td><td>Centre médical régional</td><td>Diagnostic et traitement spécialisés, traitement chirurgical, prise en charge initiale des lésions de culture, rééducation</td><td>Villes/régions/plans moyens</td></tr><tr><td>Troisième niveau</td><td>Hôpital général médical avancé</td><td>Maladies difficiles et graves, lésions de culture avancées, maladies du domaine de conscience, maladies difficiles interraciales</td><td>Noyau civilisationnel/grands plans</td></tr></tbody></table><p>En outre, une « spécialité des lésions de culture » est établie : traitant spécifiquement tous les types de lésions pendant la culture, y compris la surcharge énergétique, la rupture des méridiens, l&#39;invasion des démons du cœur, les traumatismes de l&#39;âme, etc., équipée de personnels médicaux versés dans les lois de la culture.</p><h2 id="iv-fonds-de-garantie-medicale" tabindex="-1">IV. Fonds de Garantie Médicale <a class="header-anchor" href="#iv-fonds-de-garantie-medicale" aria-label="Permalink to &quot;IV. Fonds de Garantie Médicale&quot;">​</a></h2><p>Le Fonds de Garantie Médicale est la base économique du fonctionnement du système médical symbiotique, avec des sources comprenant :</p><ul><li>Dotations de l&#39;accumulation publique (source principale)</li><li>Retenues de garantie médicale dans le Mécanisme de Contrat Conjoint de Production</li><li>Dons sociaux</li><li>Revenus des investissements du fonds</li></ul><p>Le champ de paiement du fonds comprend : les frais de services médicaux de base, les frais de soins d&#39;urgence, les frais de traitement des lésions de culture, les frais de médicaments de base, les frais de rééducation, etc. Les patients ne paient qu&#39;une petite partie des dépenses à leur charge, avec des réductions et des exonérations pour ceux en difficulté financière.</p><h2 id="v-institutions-medicales-et-personnels-medicaux" tabindex="-1">V. Institutions Médicales et Personnels Médicaux <a class="header-anchor" href="#v-institutions-medicales-et-personnels-medicaux" aria-label="Permalink to &quot;V. Institutions Médicales et Personnels Médicaux&quot;">​</a></h2><ul><li><strong>Institutions médicales publiques</strong> : établies par l&#39;État ou la communauté civilisationnelle, assumant les services médicaux de base et les fonctions de santé publique, avec un financement garanti par le Fonds de Garantie Médicale.</li><li><strong>Institutions médicales privées</strong> : établies par des forces sociales conformément à la loi ; peuvent fournir des services médicaux haut de gamme, mais doivent accepter la supervision des autorités médicales compétentes et ne doivent pas refuser les patients en urgence.</li><li><strong>Institutions médicales pour autres races</strong> : institutions médicales spécialisées établies pour les besoins physiologiques des races particulières, équipées de personnels médicaux d&#39;autres races.</li><li><strong>Droits et obligations des personnels médicaux</strong> : les personnels médicaux jouissent de droits tels que la protection de l&#39;exercice, une rémunération raisonnable et la formation professionnelle, tout en portant des obligations telles que sauver les mourants et soigner les blessés, respecter les patients et garder le secret médical.</li></ul><h2 id="vi-sante-publique-et-prevention" tabindex="-1">VI. Santé Publique et Prévention <a class="header-anchor" href="#vi-sante-publique-et-prevention" aria-label="Permalink to &quot;VI. Santé Publique et Prévention&quot;">​</a></h2><p>L&#39;État établit un système de santé publique, remplissant les fonctions suivantes :</p><ol><li>Surveillance et prévention des maladies infectieuses, établissement d&#39;un mécanisme d&#39;alerte précoce des épidémies interplans.</li><li>Examens de santé à l&#39;échelle de tous les êtres et gestion des dossiers de santé.</li><li>Sensibilisation à la sécurité de la culture et conseils de prévention des lésions de culture.</li><li>Contrôle de l&#39;hygiène environnementale et de la sécurité alimentaire et pharmaceutique.</li><li>Réponse d&#39;urgence aux événements de santé publique.</li></ol><h2 id="vii-responsabilite-juridique" tabindex="-1">VII. Responsabilité Juridique <a class="header-anchor" href="#vii-responsabilite-juridique" aria-label="Permalink to &quot;VII. Responsabilité Juridique&quot;">​</a></h2><p>Les actes violant les dispositions de cette Loi supportent les responsabilités suivantes selon la gravité des circonstances :</p><ul><li>Les institutions médicales qui refusent les patients en urgence sont ordonnées de rectifier et amendées ; si des conséquences graves s&#39;ensuivent, leurs licences d&#39;exercice sont révoquées.</li><li>Les personnels médicaux dont la négligence grave cause un préjudice aux patients supportent la responsabilité d&#39;indemnisation ; dans les cas graves, leurs qualifications d&#39;exercice sont révoquées.</li><li>Les institutions médicales qui facturent en violation des règlements ou fournissent des traitements excessifs sont ordonnées de rembourser les frais et amendées.</li><li>Ceux qui divulguent la vie privée médicale des patients supportent l&#39;indemnisation du préjudice moral ; dans les cas graves, la responsabilité pénale est poursuivie.</li><li>Ceux qui produisent et vendent des médicaments contrefaits ou de qualité inférieure ont leurs gains illégaux confisqués et sont amendés ; en cas d&#39;infraction pénale, la responsabilité pénale est poursuivie.</li></ul><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>La <em>Loi sur la Garantie Médicale</em> est l&#39;incarnation de la philosophie « un chemin pour chacun » de la Civilisation Symbiotique de l&#39;Ancre dans le domaine de la santé. En établissant un système de garantie médicale à couverture universelle, en créant une spécialité des lésions de culture et en garantissant le droit aux soins d&#39;urgence, elle assure que chaque vie puisse recevoir un traitement rapide en cas de blessure ou de maladie, posant des fondations sanitaires solides pour la progression commune des Dix Mille Races.</p><h2 id="documents-connexes" tabindex="-1">Documents Connexes <a class="header-anchor" href="#documents-connexes" aria-label="Permalink to &quot;Documents Connexes&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Constitution Symbiotique : Principes Généraux)</li><li>38-共生医疗体系 (Système Médical Symbiotique)</li><li>45-住房保障法 (Loi sur la Garantie du Logement)</li><li>08-人人有路保障体系 (Système de Garantie d&#39;un Chemin pour Chacun)</li></ul>',29)])])}const v=t(n,[["render",r]]);export{p as __pageData,v as default};
